package net.officefloor.hq.app.claim;

import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.setting.SettingStore;
import net.officefloor.hq.app.sheet.SheetStore;

/** How a sheet rounds a claim's live figures (its rate step and late charge): a claim dated before the
 *  sheet's policy date (the one set, else the sheet's today) rounds half up, one dated on or after it
 *  half to even. A correction rounds by the date of the claim it corrects, not its own. */
public final class Rounding {

    private final LocalDate policyDate;

    /** The date of each opened claim on the sheet, by its person and number. */
    private final Map<String, LocalDate> dates = new HashMap<>();

    public Rounding(LocalDate policyDate, List<Claim> claims) {
        this.policyDate = policyDate;
        for (Claim claim : claims) {
            if (claim.getNumber() != null) {
                dates.put(key(claim.getPersonId(), claim.getNumber()), claim.getDate());
            }
        }
    }

    /** The sheet's rounding, knowing every claim on it (so a correction finds the claim it corrects). */
    public static Rounding of(String sheetId, SettingStore settings, SheetStore sheets, ClaimStore claims) {
        LocalDate policy = settings.policyDate(sheetId);
        return new Rounding(policy != null ? policy : sheets.today(sheetId), claims.list(sheetId));
    }

    /** The date the claim rounds by: its own, or for a correction the date of the claim it corrects. */
    public LocalDate date(Claim claim) {
        LocalDate date = claim.getDate();
        if (claim.getCorrects() != null) {
            date = dates.getOrDefault(key(claim.getPersonId(), claim.getCorrects()), date);
        }
        return date;
    }

    /** The rounding of the claim's live figures. */
    public RoundingMode mode(Claim claim) {
        return policyDate != null && date(claim).isBefore(policyDate) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
    }

    private static String key(long personId, long number) {
        return personId + "/" + number;
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonStore;
import net.officefloor.hq.app.rate.RateStore;
import net.officefloor.hq.app.setting.SettingStore;
import net.officefloor.hq.app.sheet.SheetStore;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Moves the claim to the new status, refusing a change its current status does not allow. Opening
 *  gives the claim the sheet's next number and records who opened it; a voided claim keeps its number, which is never reused. Settling fixes its due at its person's
 *  grade rate in force on the claim's date, rounded as the sheet's policy date has it and at least the sheet's floor (none when no rate of the grade applies then),
 *  or at the figure its person's last statement bound it to, plus the late charge it has then (frozen in).
 *  The user who opened a claim may not settle it. */
public class ApplyStatus {
    public void apply(@Val StatusInput input, @Val Claim claim, ClaimStore store, PersonStore people,
            RateStore rates, SettingStore settings, SheetStore sheets, Out<StatusChange> change)
            throws InvalidSheetException {
        ClaimStatus from = claim.getStatus();
        if (input.status() == ClaimStatus.SETTLED && claim.getOpenedBy() != null
                && claim.getOpenedBy().equals(input.user())) {
            throw new InvalidSheetException("The user who opened a claim cannot settle it");
        }
        if (!from.canBecome(input.status()) || !store.move(claim, from, input.status())) {
            throw new InvalidSheetException("A " + from + " claim cannot become " + input.status());
        }
        // The due to freeze is worked out while the claim is still OPEN, so it takes its late charge in.
        BigDecimal settledDue = null;
        if (input.status() == ClaimStatus.SETTLED) {
            Person person = people.find(claim.getSheetId(), claim.getPersonId());
            BigDecimal pct = person == null ? null : rates.find(claim.getSheetId(), person.gradeOn(claim.getDate()), claim.getDate());
            settledDue = Lateness.of(claim.getSheetId(), settings, sheets, store).due(claim, pct, settings.floor(claim.getSheetId()));
        }
        claim.setStatus(input.status());
        if (input.status() == ClaimStatus.OPEN) {
            claim.setNumber(store.nextNumber(claim.getSheetId()));
            claim.setOpenedBy(input.user());
        }
        if (input.status() == ClaimStatus.SETTLED) {
            claim.setSettledDue(settledDue);
        }
        change.set(new StatusChange(claim.getNumber()));
    }
}
package net.officefloor.hq.app.claim;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.period.PeriodStore;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonStore;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Opens each selected claim that can be opened, in list order: its people in the order they were
 *  added, a person's claims newest first. Each is opened as a single open would be (the sheet's next
 *  number, opened-by the user) and recorded as CLAIM_OPENED, then how it moved the sheet's figures.
 *  A claim that is not on the sheet, is not a DRAFT, or is dated in a closed period is refused and
 *  left as it is. */
public class OpenClaims {
    public void open(@PathVariable("sheetId") String sheetId, @Val BulkOpenInput input, ClaimStore store,
            PersonStore people, PeriodStore periods, RollupService rollups, Audit audit, Out<BulkOpenResult> result) {
        String sheet = sheetId.trim();
        Map<Long, Integer> personOrder = new HashMap<>();
        Map<Long, Person> persons = new HashMap<>();
        for (Person person : people.list(sheet)) {
            personOrder.put(person.getId(), personOrder.size());
            persons.put(person.getId(), person);
        }
        int refused = 0;
        List<Claim> selected = new ArrayList<>();
        for (Long id : input.claimIds()) {
            Claim claim = id == null ? null : store.find(sheet, id);
            if (claim == null) {
                refused++;
            } else {
                selected.add(claim);
            }
        }
        selected.sort(Comparator.<Claim>comparingInt(c -> personOrder.getOrDefault(c.getPersonId(), Integer.MAX_VALUE))
                .thenComparing(Comparator.comparingLong(Claim::getId).reversed()));
        int opened = 0;
        for (Claim claim : selected) {
            if (!claim.getStatus().canBecome(ClaimStatus.OPEN) || closed(periods, claim)) {
                refused++;
                continue;
            }
            Rollup before = rollups.snapshot(sheet);
            if (!store.move(claim, claim.getStatus(), ClaimStatus.OPEN)) {
                refused++;
                continue;
            }
            claim.setStatus(ClaimStatus.OPEN);
            claim.setNumber(store.nextNumber(sheet));
            claim.setOpenedBy(input.user());
            store.save(claim);
            Person person = persons.get(claim.getPersonId());
            ClaimResponse shown = ClaimResponse.from(claim);
            audit.record(ClaimStatus.OPEN.event() + " sheet=" + sheet + " by=" + input.user() + " person="
                    + (person == null ? "" : person.getName()) + " amount=" + shown.amount() + " date=" + shown.date()
                    + " number=" + claim.getNumber());
            rollups.record(sheet, input.user(), before);
            opened++;
        }
        result.set(new BulkOpenResult(opened, refused));
    }

    private static boolean closed(PeriodStore periods, Claim claim) {
        try {
            CheckClaimPeriod.refuseClosed(periods, claim.getSheetId(), claim.getDate());
            return false;
        } catch (InvalidSheetException e) {
            return true;
        }
    }
}
